INSERT INTO `config` VALUES ('active_model','nvidia'),('agent_dan_cfo_fallback','claude:claude-sonnet-4-6'),('agent_dan_cfo_primary','nvidia:meta/llama-3.1-8b-instruct'),('agent_dan_cskh_fallback','claude:claude-sonnet-4-6'),('agent_dan_cskh_primary','nvidia:meta/llama-3.1-8b-instruct'),('agent_dan_logistics_fallback','claude:claude-sonnet-4-6'),('agent_dan_logistics_primary','nvidia:meta/llama-3.1-8b-instruct'),('agent_dan_ops_fallback','claude:claude-sonnet-4-6'),('agent_dan_ops_primary','nvidia:meta/llama-3.1-8b-instruct'),('agent_dan_rnd_fallback','claude:claude-sonnet-4-6'),('agent_dan_rnd_primary','nvidia:meta/llama-3.1-8b-instruct'),('chatgpt_disabled','false'),('chatgpt_model','gpt-4.1-mini'),('claude_base_url',''),('claude_disabled','true'),('claude_model','claude-haiku-4-5-20251001'),('cloudflare_disabled','false'),('cloudflare_model','@cf/meta/llama-3.1-8b-instruct'),('dashboard_password','$2a$10$xJpc0Z95b4heIMhIFXw6GOGuHVx8w872yY4uwnE/X7OVJJYjvGgQW'),('deepseek_disabled','true'),('deepseek_model','deepseek-chat'),('discord_active_model','nvidia'),('gemini_disabled','false'),('gemini_model','gemini-flash-latest'),('google_cx',''),('kimi_disabled','true'),('kimi_model','kimi-k2.6'),('learning_active_model','nvidia'),('learning_prompt_eval_ielts','Bạn là IELTS Examiner chính thức. Chấm bài dựa trên đề {{title}} và câu trả lời {{submission}}, trả JSON có overall_band và nhận xét theo tiêu chí.'),('learning_prompt_eval_tech','Bạn là Senior Interview Evaluator. Chấm câu trả lời dựa trên {{title}} và {{prompt}}, trả JSON có score, summary, strengths và improvements.'),('learning_prompt_ielts','Bạn là IELTS Examiner. Tạo {{count}} bài luyện IELTS cho {{topicName}}, cấp độ {{level}}. Chỉ trả JSON ARRAY đúng schema Learning.'),('learning_prompt_quiz','Bạn là Quiz Master. Tạo {{count}} câu hỏi trắc nghiệm cho {{topicName}}, cấp độ {{level}}, mỗi câu có 4 lựa chọn và đáp án đúng. Chỉ trả JSON ARRAY.'),('learning_prompt_rw','Bạn là chuyên gia Reading/Writing. Tạo {{count}} bài luyện cho {{topicName}}, cấp độ {{level}}. Chỉ trả JSON ARRAY đúng schema Learning.'),('learning_prompt_speaking','Bạn là huấn luyện viên Speaking. Tạo {{count}} tình huống luyện nói cho {{topicName}}, cấp độ {{level}}. Chỉ trả JSON ARRAY.'),('learning_prompt_tech','Bạn là Senior Technical Architect và Lead Interviewer. Tạo {{count}} câu hỏi thực chiến cho {{stackName}}, cấp độ {{level}}. Chỉ trả JSON ARRAY đúng schema Learning, không đánh số title, nội dung ngắn gọn và không thêm văn bản ngoài JSON.'),('learning_prompt_vocab','Bạn là giảng viên ngôn ngữ Anh. Tạo {{count}} từ vựng cho {{topicName}}, cấp độ {{level}}. Không lặp từ trong {{existingWords}}. Chỉ trả JSON ARRAY đúng schema Learning.'),('log_retention_days','60'),('notify_ielts_enabled','false'),('notify_quiz_enabled','false'),('notify_tech_enabled','false'),('notify_vocab_enabled','true'),('nvidia_disabled','true'),('nvidia_model','meta/llama-3.1-8b-instruct'),('ollama_disabled','true'),('ollama_model','llama3.1'),('openclaw_enabled','true'),('openclaw_url','https://openclaw.hpdev.name.vn'),('schedule_discord_channel_id','1482039307014246691'),('schedule_timezone','Asia/Ho_Chi_Minh'),('system_prompt','Bạn là Đần, trợ lý AI thân thiện của Phát. Luôn trả lời bằng tiếng Việt tự nhiên, ngắn gọn nhưng đủ ý, ưu tiên câu trả lời thực tế và dễ làm theo. Khi người dùng hỏi thông tin mới nhất, giá cả, tin tức, thời tiết hoặc dữ liệu có thể thay đổi, hãy gọi công cụ web_search trước khi trả lời và nêu rõ thời điểm hoặc nguồn nếu có. Khi người dùng yêu cầu lịch nhắc, từ vựng, ghi nhớ hoặc thao tác trên hệ thống, hãy dùng đúng công cụ tương ứng thay vì đoán. Không bịa dữ kiện, không nói đã làm một việc nếu chưa thực sự gọi công cụ thành công. Nếu một model hoặc công cụ lỗi, hãy bình tĩnh dùng fallback và trả lời hữu ích; không để lộ API key, mật khẩu, lỗi nội bộ hoặc stack trace. Xưng hô thân thiện, có thể dùng tao/mày khi người dùng dùng cách xưng hô đó, nhưng không xúc phạm.'),('telegram_active_model','nvidia'),('vllm_disabled','true'),('vllm_model','llama3.1'),('vocab_current_topic_no','3'),('vocab_daily_time','17:30'),('vocab_dictionary_api_url','https://api.dictionaryapi.dev/api/v2/entries/en'),('vocab_discord_channel_id','1482039307014246691'),('vocab_enabled','true'),('vocab_last_sent_date','2026-08-18'),('vocab_topic_mode','sequential'),('vocab_words_per_day','5');
