--
-- Table structure for table `learning_item`
--

DROP TABLE IF EXISTS `learning_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `learning_item` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `learning_id` int(11) NOT NULL,
  `type` varchar(50) NOT NULL,
  `title` varchar(255) NOT NULL,
  `prompt` text DEFAULT NULL,
  `level` varchar(50) DEFAULT 'medium',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`content`)),
  `sample_solution` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`sample_solution`)),
  `tags` varchar(255) DEFAULT NULL,
  `is_sent` tinyint(4) DEFAULT 0,
  `is_active` tinyint(4) DEFAULT 1,
  `created_by` varchar(50) DEFAULT 'ai',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_learning_id` (`learning_id`),
  KEY `idx_type` (`type`),
  KEY `idx_is_sent` (`is_sent`),
  CONSTRAINT `fk_learning_item_parent` FOREIGN KEY (`learning_id`) REFERENCES `learning` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1182 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

