INSERT INTO `learning_item` VALUES (3,1,'tech_question','Câu hỏi 1: Viết hàm kiểm tra xem một chuỗi có phải là số nguyên hay không?','Viết hàm kiểm tra xem một chuỗi có phải là số nguyên hay không? Ví dụ: isInteger(\'123\') => true, isInteger(\'abc\') => false','beginner','{\"quick_answer\":\"Sử dụng hàm is_numeric() và is_int() để kiểm tra\",\"detailed_answer\":\"Phân tích về cách sử dụng hàm is_numeric() và is_int() để kiểm tra xem một chuỗi có phải là số nguyên hay không\",\"code_example\":\"function isInteger($str) { return is_numeric($str) && is_int((int)$str); }\",\"interview_tips\":\"Bẫy: Không sử dụng hàm is_numeric() vì nó không chỉ kiểm tra số nguyên\",\"practical_tips\":\"Kinh nghiệm thực chiến: Sử dụng hàm is_int() để kiểm tra số nguyên\"}','{\"key_takeaways\":\"Sử dụng is_numeric() và is_int()\"}','php, interview, beginner',0,1,'ai','2026-08-14 17:36:22','2026-08-14 17:36:22'),(5,7,'vocabulary','wake up',NULL,'medium','{\"word\": \"wake up\", \"meaning\": \"thức dậy\", \"pronunciation\": \"\", \"example\": \"I wake up early on weekdays because my office is far from home.\", \"note\": \"Tôi thức dậy sớm vào các ngày trong tuần vì công ty khá xa nhà.\"}',NULL,NULL,1,1,'legacy_import','2026-08-14 22:58:05','2026-08-16 16:10:12'),(6,7,'vocabulary','get up',NULL,'medium','{\"word\": \"get up\", \"meaning\": \"thức dậy\", \"pronunciation\": \"\", \"example\": \"After dinner, I usually get up for about thirty minutes during the weekend.\", \"note\": \"Sau bữa tối, tôi thường thức dậy khoảng ba mươi phút vào cuối tuần.\"}',NULL,NULL,0,1,'legacy_import','2026-08-14 22:58:05','2026-08-14 22:58:05'),(7,7,'vocabulary','sleep',NULL,'medium','{\"word\": \"sleep\", \"meaning\": \"ngủ\", \"pronunciation\": \"sliːp\", \"example\": \"My roommate forgot to sleep before leaving the apartment.\", \"note\": \"Bạn cùng phòng của tôi quên ngủ trước khi rời căn hộ.\"}',NULL,NULL,0,1,'legacy_import','2026-08-14 22:58:05','2026-08-14 22:58:05'),(8,7,'vocabulary','eat',NULL,'mediu